REPLACE INTO email_templates (id, date_entered, date_modified, modified_user_id, created_by, published, name, description, subject, body, body_html, deleted, assigned_user_id, text_only, type) VALUES
('befd67fa-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Credenciales del portal (Personas)','Se envía cuando un usuario del CRM envía una invitación de portal a una Persona','Tus credenciales de acceso al portal','Hola $contact_first_name,\n\nSe ha creado tu cuenta del portal de SinergiaCRM. Es la primera vez que accedes.\n\nPRIMER PASO: Establece tu contraseña antes de intentar iniciar sesión. Usa este enlace seguro para elegirla:\n$portal_reset_link\n\nDESPUÉS DE ESTABLECER TU CONTRASEÑA:\nAplicación: $portal_app_name\nAcceso: $portal_address\nUsuario del portal: $contact_stic_portal_username_c\n\nEl enlace para establecer la contraseña caduca en 24 horas. Si no esperabas esta invitación, contacta con tu organización.','<p>Hola $contact_first_name,</p><p>Se ha creado tu cuenta del portal de SinergiaCRM. Es la primera vez que accedes.</p><p><strong>Primer paso: Establece tu contraseña antes de iniciar sesión.</strong> Usa el enlace seguro de abajo para elegirla.</p><p><a href=\"$portal_reset_link\">Establecer contraseña</a></p><p><strong>Después de establecer tu contraseña, inicia sesión con:</strong></p><p>Aplicación: $portal_app_name<br>Acceso: <a href=\"$portal_address\">$portal_address</a><br>Usuario del portal: $contact_stic_portal_username_c</p><p>El enlace para establecer la contraseña caduca en 24 horas. Si no esperabas esta invitación, contacta con tu organización.</p>',0,'1',0,'email'),
('befe7460-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Credenciales del portal (Organizaciones)','Se envía cuando un usuario del CRM envía una invitación de portal a una Organización','Tus credenciales de acceso al portal','Hola,\n\nSe ha creado la cuenta del portal de tu organización. Es la primera vez que accede.\n\nPRIMER PASO: Establece la contraseña antes de intentar iniciar sesión. Usa este enlace seguro para elegirla:\n$portal_reset_link\n\nDESPUÉS DE ESTABLECER LA CONTRASEÑA:\nAplicación: $portal_app_name\nAcceso: $portal_address\nUsuario del portal: $account_stic_portal_username_c\n\nEl enlace para establecer la contraseña caduca en 24 horas. Si no esperabas esta invitación, contacta con tu organización.','<p>Hola,</p><p>Se ha creado la cuenta del portal de tu organización. Es la primera vez que accede.</p><p><strong>Primer paso: Establece la contraseña antes de iniciar sesión.</strong> Usa el enlace seguro de abajo para elígela.</p><p><a href=\"$portal_reset_link\">Establecer contraseña</a></p><p><strong>Después de establecer la contraseña, inicia sesión con:</strong></p><p>Aplicación: $portal_app_name<br>Acceso: <a href=\"$portal_address\">$portal_address</a><br>Usuario del portal: $account_stic_portal_username_c</p><p>El enlace para establecer la contraseña caduca en 24 horas. Si no esperabas esta invitación, contacta con tu organización.</p>',0,'1',0,'email'),
('beff7975-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Restablecimiento de contraseña del portal','Se envía cuando un usuario solicita un restablecimiento de contraseña','Solicitud de restablecimiento de contraseña','Hola,\n\nSe ha solicitado un restablecimiento de contraseña para $portal_app_name. Haz clic para restablecerla (válido 1 hora): $portal_reset_link\n\nIgnóvalo si no lo has solicitado.','<p>Hola,</p><p>Se ha solicitado un restablecimiento de contraseña para <strong>$portal_app_name</strong>. Haz clic para restablecerla (válido 1 hora): <a href=\"$portal_reset_link\">Restablecer contraseña</a></p><p>Ignóvalo si no lo has solicitado.</p>',0,'1',0,'email'),
('bf00573f-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Magic link del portal','Se envía cuando un usuario solicita un magic link para iniciar sesión','Tu enlace de acceso','Hola,\n\nHaz clic para iniciar sesión: $portal_magic_link\n\nIgnóvalo si no lo has solicitado.','<p>Hola,</p><p>Haz clic para iniciar sesión: <a href=\"$portal_magic_link\">Iniciar sesión en el portal</a></p><p>Ignóvalo si no lo has solicitado.</p>',0,'1',0,'email'),
('bf0102a9-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Notificación del portal - Contraseña cambiada','Se envía cuando un usuario del portal cambia su contraseña','$portal_title - Tu contraseña ha sido cambiada','Tu contraseña del portal se cambió a las $notification_time desde la IP $notification_ip.\n\nContacta con soporte si no has sido tú.','<p>Tu contraseña del portal se cambió a las $notification_time desde la IP $notification_ip.</p><p>Contacta con soporte si no has sido tú.</p>',0,'1',0,'email'),
('bf01ff0f-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Notificación del portal - Nuevo acceso','Se envía cuando se detecta un nuevo acceso','$portal_title - Nuevo acceso detectado','Nuevo acceso a las $notification_time.\n\nIP: $notification_ip\nNavegador: $notification_ua\n\nContacta con soporte si no has sido tú.','<p>Nuevo acceso a las $notification_time.</p><p>IP: $notification_ip</p><p>Navegador: $notification_ua</p><p>Contacta con soporte si no has sido tú.</p>',0,'1',0,'email'),
('bf02dda3-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Notificación del portal - Cuenta bloqueada','Se envía cuando se bloquea una cuenta de portal','$portal_title - Cuenta bloqueada','Cuenta bloqueada por intentos fallidos a las $notification_time desde la IP $notification_ip.\n\nSe desbloqueará automáticamente, o contacta con soporte.','<p>Cuenta bloqueada por intentos fallidos a las $notification_time desde la IP $notification_ip.</p><p>Se desbloqueará automáticamente, o contacta con soporte.</p>',0,'1',0,'email'),
('bf03d86f-6017-11f1-8186-2299bea897ad',NOW(),NOW(),'1','1','yes','Ejemplo - Notificación del portal - Restablecimiento solicitado','Se envía cuando se solicita un restablecimiento de contraseña','$portal_title - Restablecimiento de contraseña solicitado','Restablecimiento solicitado a las $notification_time desde la IP $notification_ip.\n\nContacta con soporte si no has sido tú.','<p>Restablecimiento solicitado a las $notification_time desde la IP $notification_ip.</p><p>Contacta con soporte si no has sido tú.</p>',0,'1',0,'email');
